select set_config('lumiscore.catalog_release_receipt','{"rows":[{"key":{"work_id":987162003,"language":"nl"},"seq":1,"relation":"catalog_work_descriptions","after_row":{"text":"Na de lange kustwandeling die zij in Het zoutpad beschreef, probeert Raynor Winn opnieuw een leven onder een dak op te bouwen. In haar relaas blijven zij en haar man Moth zich verbonden voelen met het landschap waarin zij onderweg leefden. Een aanbod brengt hen naar een boerderij in Cornwall, waar zij de grond weer ruimte voor natuur willen geven. Winn verbindt dat nieuwe begin met herinneringen, verlies en haar verhouding tot Moth. Het boek presenteert haar eigen ervaring van thuiskomen en buiten zijn.","work_id":987162003,"evidence":[{"note":"Exact existingDutchISBN9789463821049 andindependentlyreviewedWinnmemoir; narrative attributed, notverifiedlifefacts ormedicalclaim. Reuse existingWork5185/Edition5344.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p426420047"],"reference":"work:5185","checked_at":"2026-11-03T12:39:49.425Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-amendment-029.json","sources":["https://www.penguinrandomhouse.com/books/647652/the-wild-silence-by-raynor-winn/","https://data.bibliotheken.nl/id/nbt/p426420047"]},{"note":"Exact earliertransportfailure/unpublishedarchive retained, noretryorclaimofabsence. Actualhosteddecodedcoverorplaceholderseparatelyrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789463821049","status":"no_verified_asset_retained","attempts":[{"status":"prior_source_failure_no_new_request","coverId":13010849,"receipt":"cover-archive-v2-readback.json","receiptSha256":"01f189d7785da46ad38b728eded6972350e6dbc066a98d304fcd35be46e12f27","historicalFailure":{"reference":"cover-archive-v2-readback.json","archiveUrl":"https://archive.org/download/covers_0013/covers_0013_01.zip","sourceError":"Image member checksum/type mismatch","noNewRequest":true